/**
 * JARVIS Configuration Module
 * Configurações centralizadas para o GitHub Pages
 */

window.jarvisConfig = {
    // URLs da API
    API_URLS: {
        primary: 'https://jarvis-tdgt.onrender.com',
        fallback: 'https://jarvis-api-backup.onrender.com'
    },
    
    // Configurações gerais
    settings: {
        apiTimeout: 45000,
        language: 'pt-BR',
        debugMode: true
    },
    
    // Detectar ambiente
    getEnvironment: function() {
        return window.location.hostname.includes('github.io') ? 'github-pages' : 'local';
    },
    
    // Obter URL da API
    getApiUrl: function() {
        const customUrl = localStorage.getItem('FRONT_API_URL');
        if (customUrl) {
            return customUrl;
        }
        return this.API_URLS.primary;
    },
    
    // Configurar URL da API
    configureApiUrl: function() {
        const current = this.getApiUrl();
        const newUrl = prompt(`Configurar URL da API:

Atual: ${current}
Padrão: ${this.API_URLS.primary}

Digite a nova URL ou deixe vazio para usar a padrão:`, current);
        
        if (newUrl === null) return; // Cancelado
        
        const trimmed = (newUrl || '').trim();
        if (trimmed === '' || trimmed === this.API_URLS.primary) {
            localStorage.removeItem('FRONT_API_URL');
            alert(`✅ Usando API padrão: ${this.API_URLS.primary}`);
        } else {
            localStorage.setItem('FRONT_API_URL', trimmed);
            alert(`✅ API configurada: ${trimmed}`);
        }
    },
    
    // Testar conectividade
    testConnectivity: async function() {
        const apiUrl = this.getApiUrl();
        console.log('🔍 Testando conectividade:', apiUrl);
        
        try {
            const response = await fetch(`${apiUrl}/health`, {
                method: 'GET',
                timeout: 10000
            });
            
            if (response.ok) {
                const data = await response.json();
                alert(`✅ API funcionando!
                
Status: ${data.status || 'OK'}
URL: ${apiUrl}
Tempo de resposta: ${Date.now() - startTime}ms`);
                return true;
            } else {
                throw new Error(`HTTP ${response.status}`);
            }
        } catch (error) {
            console.error('❌ Erro de conectividade:', error);
            alert(`❌ Erro de conectividade:

${error.message}

Verifique:
• Sua conexão com a internet
• Se a URL da API está correta
• Se o servidor está online`);
            return false;
        }
    },
    
    // Diagnóstico completo
    diagnose: async function() {
        console.log('🔍 Executando diagnóstico...');
        
        const diagnosis = {
            environment: this.getEnvironment(),
            apiUrl: this.getApiUrl(),
            apiConnectivity: false,
            speechRecognition: false,
            textToSpeech: false,
            browser: navigator.userAgent,
            timestamp: new Date().toISOString()
        };
        
        // Testar API
        try {
            const response = await fetch(`${this.getApiUrl()}/health`, { timeout: 5000 });
            diagnosis.apiConnectivity = response.ok;
        } catch (error) {
            console.warn('API não acessível:', error);
        }
        
        // Testar Speech Recognition
        diagnosis.speechRecognition = 'webkitSpeechRecognition' in window || 'SpeechRecognition' in window;
        
        // Testar Text-to-Speech
        diagnosis.textToSpeech = 'speechSynthesis' in window;
        
        console.log('📊 Diagnóstico completo:', diagnosis);
        return diagnosis;
    },
    
    // Configurações rápidas
    showQuickSettings: function() {
        const options = [
            '🔧 Configurar URL da API',
            '🌐 Testar Conectividade',
            '🎤 Testar Microfone',
            '🔊 Testar Text-to-Speech',
            '📊 Diagnóstico Completo',
            '📝 Ver Logs do Console',
            '❌ Cancelar'
        ];
        
        const choice = prompt(`⚙️ Configurações Rápidas do JARVIS

${options.map((opt, i) => `${i + 1}. ${opt}`).join('\\n')}

Escolha uma opção (1-${options.length}):`);
        
        if (window.jarvisSettingsHandler) {
            window.jarvisSettingsHandler(choice);
        } else {
            this.handleSettingsChoice(choice);
        }
    },
    
    // Handler padrão para configurações
    handleSettingsChoice: function(choice) {
        switch(choice) {
            case '1':
                this.configureApiUrl();
                break;
            case '2':
                this.testConnectivity();
                break;
            case '3':
                this.testMicrophone();
                break;
            case '4':
                this.testTTS();
                break;
            case '5':
                this.showDiagnosis();
                break;
            case '6':
                this.showConsoleLogs();
                break;
            default:
                return;
        }
    },
    
    // Testar microfone
    testMicrophone: async function() {
        if (!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
            alert('❌ Reconhecimento de voz não suportado neste navegador.');
            return false;
        }
        
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            stream.getTracks().forEach(track => track.stop());
            alert('✅ Microfone funcionando corretamente!');
            return true;
        } catch (error) {
            alert(`❌ Problema com o microfone:

${error.message}

Verifique as permissões do navegador.`);
            return false;
        }
    },
    
    // Testar TTS
    testTTS: function() {
        if (!('speechSynthesis' in window)) {
            alert('❌ Text-to-Speech não suportado neste navegador.');
            return false;
        }
        
        try {
            const utterance = new SpeechSynthesisUtterance('Teste do sistema de voz do Jarvis funcionando perfeitamente!');
            utterance.lang = 'pt-BR';
            utterance.rate = 1;
            utterance.pitch = 1;
            speechSynthesis.speak(utterance);
            alert('✅ Teste de voz executado! Você deve ouvir uma mensagem.');
            return true;
        } catch (error) {
            alert(`❌ Erro no sistema de voz: ${error.message}`);
            return false;
        }
    },
    
    // Mostrar diagnóstico
    showDiagnosis: async function() {
        const diagnosis = await this.diagnose();
        
        const report = `📊 DIAGNÓSTICO DO SISTEMA JARVIS

🌐 Ambiente: ${diagnosis.environment}
🔗 API URL: ${diagnosis.apiUrl}
📶 Conectividade API: ${diagnosis.apiConnectivity ? '✅' : '❌'}
🎤 Reconhecimento de Voz: ${diagnosis.speechRecognition ? '✅' : '❌'}
🔊 Text-to-Speech: ${diagnosis.textToSpeech ? '✅' : '❌'}
🌐 Navegador: ${diagnosis.browser.split(' ').pop()}
⏰ Timestamp: ${diagnosis.timestamp}

${diagnosis.apiConnectivity ? 
    '✅ Sistema funcionando normalmente!' : 
    '⚠️ Problemas de conectividade detectados!'}`;
        
        alert(report);
    },
    
    // Mostrar logs do console
    showConsoleLogs: function() {
        alert(`📝 LOGS DO CONSOLE

Para ver os logs detalhados:

1. Pressione F12 para abrir DevTools
2. Clique na aba "Console"
3. Procure por mensagens com emojis:
   🤖 Inicialização
   🎤 Reconhecimento de voz
   🔊 Text-to-Speech
   📶 Conexões de API
   ❌ Erros e avisos

Os logs são atualizados em tempo real!`);
        
        console.log('📝 === LOGS DO JARVIS ===');
        console.log('🤖 Sistema:', this.getEnvironment());
        console.log('🔗 API:', this.getApiUrl());
        console.log('⚙️ Configurações:', this.settings);
    }
};

// Inicializar configurações
console.log('⚙️ JARVIS Config carregado!');
console.log('🌐 Ambiente:', window.jarvisConfig.getEnvironment());
console.log('🔗 API URL:', window.jarvisConfig.getApiUrl());